pub fn worth_indexing_2(vm: &mut WamState, a1: Value, a2: Value) -> bool {
    let (code, labels) = get_shared_wam();
    vm.code = code.clone();
    vm.labels = labels.clone();
    vm.pc = 4918;
    vm.set_reg("A1", a1);
    vm.set_reg("A2", a2);
    vm.run()
}

